    created_at, updated_at, raw_app_meta_data, raw_user_meta_data,
    confirmation_token, recovery_token, email_change_token_new, email_change
) VALUES
('00000000-0000-0000-0000-000000000000', '66666666-6666-4666-8666-666666666666', 'authenticated', 'authenticated', 'fansa@estufas.local', crypt('ComercialFansa123!', gen_salt('bf')), now(), now(), now(), '{"provider":"email","providers":["email"]}', '{"rol":"comercial","nombre":"Comercial Fansa"}', '', '', '', ''),
('00000000-0000-0000-0000-000000000000', '77777777-7777-4777-8777-777777777777', 'authenticated', 'authenticated', 'ambos@estufas.local', crypt('ComercialAmbos123!', gen_salt('bf')), now(), now(), now(), '{"provider":"email","providers":["email"]}', '{"rol":"comercial","nombre":"Comercial Ambos"}', '', '', '', '')
